// --- Data Models ---

case class CasePerson(name: String, age: Int, email: String)

class RegularPerson(val name: String, val age: Int, val email: String) {
  def this() = this("", 0, "")
}

@BenchmarkMode(Array(Mode.AverageTime))
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 5, time = 1s)
@Measurement(iterations = 10, time = 1s)
@State(Scope.Thread)
class CaseClassBenchmark {

  @Benchmark
  def instantiateCaseClass(bh: Blackhole): Unit = {
    bh.consume(CasePerson("Alice", 30, "alice@example.com"))
  }

  @Benchmark
  def instantiateRegularClass(bh: Blackhole): Unit = {
    bh.consume(new RegularPerson("Alice", 30, "alice@example.com"))
  }

  @Benchmark
  def accessCaseClassFields(bh: Blackhole): Unit = {
    val p = CasePerson("Alice", 30, "alice@example.com")
    bh.consume(p.name)
    bh.consume(p.age)
    bh.consume(p.email)
  }

  @Benchmark
  def accessRegularClassFields(bh: Blackhole): Unit = {
    val p = new RegularPerson("Alice", 30, "alice@example.com")
    bh.consume(p.name)
    bh.consume(p.age)
    bh.consume(p.email)
  }

  @Benchmark
  def copyCaseClass(bh: Blackhole): Unit = {
    val p = CasePerson("Alice", 30, "alice@example.com")
    bh.consume(p.copy(age = 31))
  }

  @Benchmark
  def manualCopyRegularClass(bh: Blackhole): Unit = {
    val p = new RegularPerson("Alice", 30, "alice@example.com")
    bh.consume(new RegularPerson(p.name, 31, p.email))
  }
}
```

