import java.lang.reflect.*;

public class SortBenchmark {
    static final int N = 14_302;
    static final int RUNS = 1000;

    // Generate partially sorted data with few random inversion clusters
    static int[] generateTestData() {
        int[] arr = new int[N];
        for (int i = 0; i < N; i++) arr[i] = i; // start fully sorted

        // Add ~5% random swaps creating small inversion clusters
        Random rng = new Random(42);
        int numSwaps = N / 20; // ~715 swaps
        for (int s = 0; s < numSwaps; s++) {
            int i = rng.nextInt(N);
            int j = i + 1 + rng.nextInt(Math.min(50, N - i - 1));
            if (j < N) {
                int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
            }
        }
        return arr;
    }

    public static void main(String[] args) throws Exception {
        // Warm up JVM
        for (int w = 0; w < 100; w++) {
            int[] warmup = generateTestData();
            Arrays.sort(warmup);
        }

        long timsortTotal = 0;
        long dualPivotTotal = 0;

        for (int r = 0; r < RUNS; r++) {
            // --- Timsort (via Integer[]) ---
            Integer[] objArr = generateTestData().boxed().toArray(Integer[]::new);
            long start = System.nanoTime();
            Arrays.sort(objArr);
            timsortTotal += System.nanoTime() - start;

            // --- Dual-Pivot Quicksort (via int[]) ---
            int[] primArr = generateTestData();
            start = System.nanoTime();
            Arrays.sort(primArr); // JDK 7+ uses Dual-Pivot Quicksort for primitives
            dualPivotTotal += System.nanoTime() - start;
