    public static class State {
        double x = 1.0;
        double y = 2.0;
    }

    // Plain class instance creation
    @Benchmark
    public Object createPlain(State s) {
        return new Point(s.x, s.y);
    }

    // Case class via apply
    @Benchmark
    public Object createCaseApply(State s) {
        return PointCC$.MODULE$.apply(s.x, s.y);
    }

    // Case class via new
    @Benchmark
    public Object createCaseNew(State s) {
        return new PointCC(s.x, s.y);
    }

    // Field read after creation
    @Benchmark
    public double readCaseField(State s) {
        PointCC p = new PointCC(s.x, s.y);
        return p.x();
    }

    @Benchmark
    public double readPlainField(State s) {
        Point p = new Point(s.x, s.y);
        return p.xVal;
    }
}
```

