#include <stdio.h>
#include <stdlib.h>
#include <time.h>

void insertion_sort(int* a, int n) {
    for (int i = 1; i < n; i++) {
        int k = a[i];
        int j = i;
        while (j > 0 && a[j-1] > k) { a[j] = a[j-1]; j--; }
        a[j] = k;
    }
}

void quicksort(int* a, int l, int r) {
    if (r - l <= 16) { insertion_sort(a + l, r - l + 1); return; }
    int m = (l + r) / 2;
    int pivot = a[m];
    int i = l, j = r;
    do { while (a[i] < pivot) i++; while (a[j] > pivot) j--;
          if (i <= j) { int t = a[i]; a[i] = a[j]; a[j] = t; i++; j--; }
    } while (i <= j);
    if (l < j) quicksort(a, l, j);
    if (i < r) quicksort(a, i, r);
}

